import torch
import torch.nn as nn
import math
from torch.utils.cpp_extension import load_inline

conv_transpose3d_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

__global__ void conv_transpose3d_kernel(
    const float* input,
    const float* weight,
    const float* bias,
    float* output,
    int batch_size,
    int in_channels,
    int in_depth,
    int in_height,
    int in_width,
    int out_channels,
    int out_depth,
    int out_height,
    int out_width,
    int kernel_depth,
    int kernel_width,
    int kernel_height,
    int stride_depth,
    int stride_width,
    int stride_height,
    int padding_depth,
    int padding_width,
    int padding_height,
    int groups,
    bool has_bias) {

    int total_elements = batch_size * out_channels * out_depth * out_height * out_width;
    int idx = blockIdx.x * blockDim.x + threadIdx.x;

    if (idx >= total_elements) return;

    // Unravel 5D indices
    int batch = idx / (out_channels * out_depth * out_height * out_width);
    int rem = idx % (out_channels * out_depth * out_height * out_width);
    int oc = rem / (out_depth * out_height * out_width);
    rem = rem % (out_depth * out_height * out_width);
    int od = rem / (out_height * out_width);
    rem = rem % (out_height * out_width);
    int oh = rem / out_width;
    int ow = rem % out_width;

    float val = 0.0f;

    int group_size = out_channels / groups;
    int g = oc / group_size;
    int oc_in_group = oc % group_size;
    int ic_start = g * (in_channels / groups);

    for (int kd = 0; kd < kernel_depth; kd++) {
        for (int kh = 0; kh < kernel_height; kh++) {
            for (int kw = 0; kw < kernel_width; kw++) {
                int id = (od + padding_depth - kd) / stride_depth;
                int ih = (oh + padding_height - kh) / stride_height;
                int iw = (ow + padding_width - kw) / stride_width;

                if ((od + padding_depth - kd) % stride_depth != 0) continue;
                if ((oh + padding_height - kh) % stride_height != 0) continue;
                if ((ow + padding_width - kw) % stride_width != 0) continue;
                if (id < 0 || id >= in_depth) continue;
                if (ih < 0 || ih >= in_height) continue;
                if (iw < 0 || iw >= in_width) continue;

                for (int ic = 0; ic < in_channels/groups; ic++) {
                    int input_idx = batch * in_channels * in_depth * in_height * in_width +
                                   (ic_start + ic) * in_depth * in_height * in_width +
                                   id * in_height * in_width +
                                   ih * in_width +
                                   iw;

                    int weight_idx = (ic_start + ic) * (out_channels/groups * kernel_depth * kernel_height * kernel_width) +
                                    oc_in_group * kernel_depth * kernel_height * kernel_width +
                                    kd * kernel_height * kernel_width +
                                    kh * kernel_width +
                                    kw;

                    val += input[input_idx] * weight[weight_idx];
                }
            }
        }
    }

    if (has_bias) val += bias[oc];
    output[idx] = val;
}

torch::Tensor conv_transpose3d_cuda(
    torch::Tensor input,
    torch::Tensor weight,
    torch::Tensor bias,
    int out_depth,
    int out_height,
    int out_width,
    int kernel_depth,
    int kernel_width,
    int kernel_height,
    int stride_depth,
    int stride_width,
    int stride_height,
    int padding_depth,
    int padding_width,
    int padding_height,
    int groups,
    bool has_bias) {

    auto output = torch::zeros({input.size(0), 
                               weight.size(1) * groups,
                               out_depth,
                               out_height,
                               out_width}, input.options());

    int total_elements = output.numel();
    int block_size = 256;
    int grid_size = (total_elements + block_size - 1) / block_size;

    conv_transpose3d_kernel<<<grid_size, block_size>>>(
        input.data_ptr<float>(),
        weight.data_ptr<float>(),
        has_bias ? bias.data_ptr<float>() : nullptr,
        output.data_ptr<float>(),
        input.size(0),
        input.size(1),
        input.size(2),
        input.size(3),
        input.size(4),
        output.size(1),
        out_depth,
        out_height,
        out_width,
        kernel_depth,
        kernel_width,
        kernel_height,
        stride_depth,
        stride_width,
        stride_height,
        padding_depth,
        padding_width,
        padding_height,
        groups,
        has_bias
    );

    return output;
}
"""

conv_transpose3d_cpp = """
torch::Tensor conv_transpose3d_cuda(
    torch::Tensor input,
    torch::Tensor weight,
    torch::Tensor bias,
    int out_depth,
    int out_height,
    int out_width,
    int kernel_depth,
    int kernel_width,
    int kernel_height,
    int stride_depth,
    int stride_width,
    int stride_height,
    int padding_depth,
    int padding_width,
    int padding_height,
    int groups,
    bool has_bias);
"""

conv_transpose3d_ext = load_inline(
    name="conv_transpose3d",
    cpp_sources=conv_transpose3d_cpp,
    cuda_sources=conv_transpose3d_source,
    functions=["conv_transpose3d_cuda"],
    verbose=True
)

class ModelNew(nn.Module):
    def __init__(self, in_channels, out_channels, kernel_size, stride=(1,1,1), 
                 padding=(0,0,0), output_padding=(0,0,0), groups=1, bias=False):
        super().__init__()
        self.in_channels = in_channels
        self.out_channels = out_channels
        self.kernel_size = kernel_size
        self.stride = stride
        self.padding = padding
        self.output_padding = output_padding
        self.groups = groups

        self.weight = nn.Parameter(torch.empty(
            in_channels,
            out_channels // groups,
            kernel_size[0],
            kernel_size[1],
            kernel_size[2]
        ))

        if bias:
            self.bias = nn.Parameter(torch.empty(out_channels))
        else:
            self.register_parameter('bias', None)

        self.reset_parameters()

    def reset_parameters(self):
        nn.init.kaiming_uniform_(self.weight, a=math.sqrt(5))
        if self.bias is not None:
            fan_in, _ = nn.init._calculate_fan_in_and_fan_out(self.weight)
            bound = 1 / math.sqrt(fan_in)
            nn.init.uniform_(self.bias, -bound, bound)

    def forward(self, x):
        in_depth, in_height, in_width = x.shape[2:]
        out_depth = (in_depth - 1) * self.stride[0] + self.kernel_size[0] - 2 * self.padding[0] + self.output_padding[0]
        out_height = (in_height - 1) * self.stride[1] + self.kernel_size[1] - 2 * self.padding[1] + self.output_padding[1]
        out_width = (in_width - 1) * self.stride[2] + self.kernel_size[2] - 2 * self.padding[2] + self.output_padding[2]

        return conv_transpose3d_ext.conv_transpose3d_cuda(
            x.contiguous(),
            self.weight,
            self.bias if self.bias is not None else torch.empty(0, device=x.device),
            out_depth,
            out_height,
            out_width,
            self.kernel_size[0],
            self.kernel_size[1],
            self.kernel_size[2],
            self.stride[0],
            self.stride[1],
            self.stride[2],
            self.padding[0],
            self.padding[1],
            self.padding[2],
            self.groups,
            self.bias is not None
        )
